# -*- coding: utf-8 -*-
"""Реестр решений «профиль компании → юридическое лицо», см.
pipeline/COMPANY_FINANCE_BRIEF.md, раздел «Суждение — в git-реестре,
механика — на боевом хосте».

ЗАЧЕМ ЭТОТ ФАЙЛ, А НЕ ТАБЛИЦА `legal_entity_candidates` В SQL. Сопоставление
«бренд → ИНН» — это СУЖДЕНИЕ: чтение ОКВЭД, региона, статуса против того, что
известно о компании из её сделок, а не механическое совпадение строк (уроки
CLAUDE.md — «Конкретно звучащее имя компании тоже бывает однофамильцем»,
и живые примеры ниже: «ПАО МАГНИТ» встретилось дважды с разными ИНН, один —
литейный завод в другом регионе). Прошлая проба (18 августа 2026, 124
компании) искала кандидатов и подтверждала их в ОДНОРАЗОВОМ контейнере сессии
Claude Code Remote — контейнер умер, список кандидатов пропал целиком.
Суждение живёт здесь, в git, и переживает любой контейнер; механическая
докачка отчётности по уже принятому решению — задача `sync_fns.py
--from-registry`, она выполняется там, куда достаёт `DATABASE_URL` (боевой
хост), не здесь.

ЗАКРЫТЫЙ СПИСОК РЕШЕНИЙ. У каждого профиля — ровно одна текущая запись,
и `decision` — из этого списка:

  confirmed       ИНН подтверждён чтением (ОКВЭД/регион/статус против фактов
                  о компании из её сделок) — на экране полный блок ФНС.
  bank            кредитная организация — ГИР БО не несёт коммерческих строк
                  (банки отчитываются перед ЦБ по другой форме), на экране —
                  блок Банка России, не пустая сетка «Выручка —».
  foreign         иностранное юридическое лицо без ЕГРЮЛ.
  person          профиль — физическое лицо, финансового блока не бывает.
  state_org       государственный орган/госкорпорация — не сдаёт БФО.
  lot             лот из нескольких юрлиц (см. `company.lot` в самой базе) —
                  у сделки одно поле «предмет», выбрать одно юрлицо нельзя.
  brand_needs_inn бренд не совпадает с юридическим именем, ИНН ещё не найден.
  no_match        искали, не нашли надёжного совпадения — с причиной, что
                  именно проверяли и почему не сошлось (не то же самое, что
                  «не искали вовсе»).

ФОРМАТ ЗАПИСИ. `company_id` — как в `static/data/deals_promoted.json`;
`inn`/`cbr_regnum` — если решение их даёт; `reason` — не «похоже по имени», а
что именно проверено (ОКВЭД, регион, статус, что отличает от тёзок); `date` —
когда решение принято. Дополняя реестр, дописывайте в конец соответствующего
списка ниже, партиями — как таблица `FIXES` в `pipeline/ingest/review.py`.

Проверки — в `test_data.py` (`test_fns_registry_*`): контрольная сумма ИНН,
`company_id` существует в базе, один ИНН не подтверждён двум профилям,
`reason`/`date` непустые, `decision` из этого списка, `company_id` не
повторяется (одна текущая запись на профиль).
"""
from __future__ import annotations

DECISIONS = frozenset({
    "confirmed", "bank", "foreign", "person", "state_org",
    "lot", "brand_needs_inn", "no_match",
})


def inn_is_valid(inn: str) -> bool:
    """Контрольное число ИНН по официальному алгоритму ФНС — 10 знаков для
    юрлиц, 12 для ИП/физлиц. Нужна для защиты от опечатки при переносе числа
    из результата поиска в реестр вручную."""
    if not inn or not inn.isdigit():
        return False
    digits = [int(c) for c in inn]
    if len(inn) == 10:
        weights = (2, 4, 10, 3, 5, 9, 4, 6, 8)
        control = sum(w * d for w, d in zip(weights, digits)) % 11 % 10
        return control == digits[9]
    if len(inn) == 12:
        weights1 = (7, 2, 4, 10, 3, 5, 9, 4, 6, 8)
        weights2 = (3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8)
        control1 = sum(w * d for w, d in zip(weights1, digits)) % 11 % 10
        control2 = sum(w * d for w, d in zip(weights2, digits)) % 11 % 10
        return control1 == digits[10] and control2 == digits[11]
    return False


